"""Render rows as a GitHub markdown table."""


def _line(cells):
    return "| " + " | ".join(cells) + " |"


def to_markdown(rows):
    """rows is a list of lists of strings; the first row is the header.

    Returns the table joined with newlines, without a trailing newline.
    """
    if not rows:
        raise ValueError("no rows")
    if not rows[0]:
        raise ValueError("empty header")
    width = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(f"row {i} has {len(row)} cells, expected {width}")
    cleaned = [[cell.strip().replace("|", "\\|") for cell in row] for row in rows]
    lines = [_line(cleaned[0]), _line(["---"] * width)]
    lines += [_line(row) for row in cleaned[1:]]
    return "\n".join(lines)

